using System;using System.Linq;using System.IO;using System.Collections.Generic;using System.ComponentModel;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Input;using System.Windows.Media;using System.Windows.Media.Imaging;using System.Windows.Data;
namespace FileCompass {
 internal sealed partial class QuickPreviewPane {
  sealed class PreviewChoice:INotifyPropertyChanged {internal Entry Entry;ImageSource image;public string Caption{get{return Path.GetFileName(Entry.FullPath);}}public string PathLabel{get{return Entry.FullPath;}}public ImageSource Image{get{return image;}set{image=value;if(PropertyChanged!=null)PropertyChanged(this,new PropertyChangedEventArgs("Image"));}}public event PropertyChangedEventHandler PropertyChanged;}
  readonly ListBox selectionStrip=new ListBox{BorderThickness=new Thickness(0),Padding=new Thickness(0,0,0,10),Background=Brushes.Transparent,SelectionMode=SelectionMode.Single};
  readonly Border selectionFrame=new Border{Visibility=Visibility.Collapsed,Background=CompactTheme.PanelSurface,BorderBrush=CompactTheme.Line,BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(6),Padding=new Thickness(6),Margin=new Thickness(0,5,0,7)};
  readonly TextBlock selectionCount=new TextBlock{Foreground=FluentTheme.Muted,FontSize=11,Margin=new Thickness(2,0,0,4)};
  Entry[] selectionFiles=new Entry[0];string selectionContext="";Action<Entry> openSelection;bool changingSelection,localThumbnails;int selectionGeneration;
  internal int SelectionCount{get{return selectionFiles.Length;}}internal int SelectedPreviewIndex{get{return selectionStrip.SelectedIndex;}}internal string SelectedPreviewPath{get{return selectionStrip.SelectedIndex<0?null:selectionFiles[selectionStrip.SelectedIndex].FullPath;}}
  internal bool SelectionMatches(Entry[] entries,string context){return selectionContext==context&&selectionFiles.Select(x=>x.FullPath).SequenceEqual(entries.Select(x=>x.FullPath));}
  void InitializeSelectionStrip(DockPanel body,bool compact){
   var stack=new StackPanel();stack.Children.Add(selectionCount);stack.Children.Add(selectionStrip);selectionFrame.Child=stack;DockPanel.SetDock(selectionFrame,Dock.Top);body.Children.Add(selectionFrame);
   ScrollViewer.SetHorizontalScrollBarVisibility(selectionStrip,ScrollBarVisibility.Auto);ScrollViewer.SetVerticalScrollBarVisibility(selectionStrip,ScrollBarVisibility.Disabled);VirtualizingPanel.SetIsVirtualizing(selectionStrip,true);VirtualizingPanel.SetVirtualizationMode(selectionStrip,VirtualizationMode.Recycling);ScrollViewer.SetCanContentScroll(selectionStrip,true);
   var host=new FrameworkElementFactory(typeof(VirtualizingStackPanel));host.SetValue(VirtualizingStackPanel.OrientationProperty,Orientation.Horizontal);selectionStrip.ItemsPanel=new ItemsPanelTemplate(host);
   var row=new FrameworkElementFactory(typeof(StackPanel));row.SetValue(FrameworkElement.WidthProperty,100.0);row.SetBinding(FrameworkElement.ToolTipProperty,new Binding("PathLabel"));var icon=new FrameworkElementFactory(typeof(Image));icon.SetValue(FrameworkElement.HeightProperty,compact?28.0:42.0);icon.SetValue(Image.StretchProperty,Stretch.Uniform);icon.SetBinding(Image.SourceProperty,new Binding("Image"));icon.AddHandler(FrameworkElement.LoadedEvent,new RoutedEventHandler(async delegate(object sender,RoutedEventArgs args){var element=(Image)sender;var item=element.DataContext as PreviewChoice;int generation=selectionGeneration;if(!localThumbnails||item==null||FileViewers.Kind(item.Entry.FullPath)!="image")return;var thumbnail=await Task.Run(()=>SelectionThumbnail(item.Entry.FullPath));if(generation==selectionGeneration&&thumbnail!=null)item.Image=thumbnail;}));row.AppendChild(icon);var name=new FrameworkElementFactory(typeof(TextBlock));name.SetBinding(TextBlock.TextProperty,new Binding("Caption"));name.SetValue(TextBlock.TextTrimmingProperty,TextTrimming.CharacterEllipsis);name.SetValue(TextBlock.FontSizeProperty,11.0);name.SetValue(TextBlock.TextAlignmentProperty,TextAlignment.Center);row.AppendChild(name);selectionStrip.ItemTemplate=new DataTemplate{VisualTree=row};
   var style=new Style(typeof(ListBoxItem));style.Setters.Add(new Setter(Control.PaddingProperty,new Thickness(5)));style.Setters.Add(new Setter(FrameworkElement.MarginProperty,new Thickness(0,0,5,0)));style.Setters.Add(new Setter(Control.BackgroundProperty,CompactTheme.WhiteSurface));style.Setters.Add(new Setter(Control.BorderBrushProperty,CompactTheme.Line));style.Setters.Add(new Setter(Control.TemplateProperty,(ControlTemplate)System.Windows.Markup.XamlReader.Parse(@"<ControlTemplate xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' TargetType='ListBoxItem'><Border Background='{TemplateBinding Background}' BorderBrush='{TemplateBinding BorderBrush}' BorderThickness='1' CornerRadius='4' Padding='{TemplateBinding Padding}'><ContentPresenter/></Border></ControlTemplate>")));var selected=new Trigger{Property=ListBoxItem.IsSelectedProperty,Value=true};selected.Setters.Add(new Setter(Control.BackgroundProperty,CompactTheme.ActivePath));selected.Setters.Add(new Setter(Control.BorderBrushProperty,FluentTheme.Accent));style.Triggers.Add(selected);selectionStrip.ItemContainerStyle=style;
   selectionStrip.SelectionChanged+=delegate{if(!changingSelection)OpenSelectionItem();};selectionStrip.PreviewKeyDown+=delegate(object sender,KeyEventArgs args){if(args.Key==Key.Left||args.Key==Key.Right){SelectPreviewIndex(selectionStrip.SelectedIndex+(args.Key==Key.Right?1:-1));args.Handled=true;}};
  }
  static ImageSource SelectionThumbnail(string path){try{var image=new BitmapImage();using(var stream=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete)){image.BeginInit();image.CacheOption=BitmapCacheOption.OnLoad;image.DecodePixelWidth=96;image.StreamSource=stream;image.EndInit();}image.Freeze();return image;}catch{return null;}}
  internal void SetSelection(Entry[] entries,string context,Action<Entry> open,bool thumbnails){
   openSelection=open;localThumbnails=thumbnails;if(SelectionMatches(entries,context)){if(thumbnails&&SelectedPreviewIndex>=0)open(selectionFiles[SelectedPreviewIndex]);return;}
   string previous=SelectedPreviewPath;selectionGeneration++;selectionFiles=entries;selectionContext=context;changingSelection=true;try{selectionStrip.ItemsSource=entries.Select(x=>new PreviewChoice{Entry=x,Image=x.Icon}).ToArray();int index=Array.FindIndex(entries,x=>x.FullPath==previous);selectionStrip.SelectedIndex=entries.Length==0?-1:Math.Max(0,index);}finally{changingSelection=false;}selectionFrame.Visibility=entries.Length>1?Visibility.Visible:Visibility.Collapsed;OpenSelectionItem();
  }
  internal void SelectPreviewIndex(int index){if(selectionFiles.Length==0)return;selectionStrip.SelectedIndex=Math.Max(0,Math.Min(selectionFiles.Length-1,index));if(selectionStrip.SelectedItem!=null)selectionStrip.ScrollIntoView(selectionStrip.SelectedItem);}
  void OpenSelectionItem(){int index=SelectedPreviewIndex;if(index<0||index>=selectionFiles.Length)return;selectionCount.Text=L.Text("preview.selectionTitle")+" · "+(index+1)+" / "+selectionFiles.Length;selectionFrame.ToolTip=L.Text("preview.selectionKeysHelp");if(openSelection!=null)openSelection(selectionFiles[index]);}
  void ReleaseSelection(){selectionGeneration++;selectionFiles=new Entry[0];selectionStrip.ItemsSource=null;openSelection=null;selectionFrame.Visibility=Visibility.Collapsed;}
 }
 public partial class FilePanel {
  internal event Action PreviewSelectionChanged;
  internal Entry[] PreviewEntries(){return Selected().Where(x=>!x.IsDirectory&&!x.IsParent).ToArray();}
  internal string PreviewContext{get{return IsRemote?"remote:"+Remote.Profile.Id:IsArchive?"archive:"+Archive.FilePath:IsExt?"ext":"local";}}
  internal void PreviewEntry(QuickPreviewPane pane,Entry entry){if(IsArchive)pane.ShowArchiveFile(Archive,entry.FullPath);else if(IsExt)pane.ShowExtFile(entry.FullPath);else if(IsRemote){if(Remote.Profile.Protocol==NetworkProtocol.FTP||Remote.Profile.Protocol==NetworkProtocol.SFTP)pane.ShowRemoteFile(entry.FullPath,Remote,entry.Bytes+"|"+entry.ModifiedTime.Ticks);else pane.ShowMessage(L.Text("remotePreview.ftpSftpRequired"));}else pane.ShowFile(entry.FullPath,true);}
 }
}
